def get_distance(x, y, T):
    best_d = float('inf')
    for b in range(T // y + 2):
        rem = T - b * y
        if rem < 0: break
        a = rem // x
        s = a * x + b * y
        best_d = min(best_d, abs(s - T))
        if a > 0:
            s2 = (a + 1) * x + b * y
            best_d = min(best_d, abs(s2 - T))
        if b > 0:
            s3 = a * x + (b + 1) * y
            best_d = min(best_d, abs(s3 - T))
    return best_d

